def solve(expression):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in str(expression):
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return len(stack) == 0
